import{_ as e,r as n,o,c,e as s,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const h=JSON.parse('{"title":"Пагинация - October CMS - 3.x","titleTemplate":false,"description":"Узнайте, как отображать ссылки пагинации.","frontmatter":{"subtitle":"Узнайте, как отображать ссылки пагинации."},"headers":[{"level":2,"title":"Пагинация данных","slug":"пагинация-данных","link":"#пагинация-данных","children":[{"level":3,"title":"Несколько экземпляров пагинации","slug":"несколько-экземпляров-пагинации","link":"#несколько-экземпляров-пагинации","children":[]},{"level":3,"title":"Использование пользовательской разметки пагинации","slug":"использование-пользовательскои-разметки-пагинации","link":"#использование-пользовательскои-разметки-пагинации","children":[]}]},{"level":2,"title":"AJAX-пагинация","slug":"ajax-пагинация","link":"#ajax-пагинация","children":[]},{"level":2,"title":"Пагинация «Загрузить ещё»","slug":"пагинация-«загрузить-еще»","link":"#пагинация-«загрузить-еще»","children":[{"level":4,"title":"См. также","slug":"см-также","link":"#см-также","children":[]}]}],"relativePath":"3.x/ru/cms/features/pagination.md","filePath":"3.x/ru/cms/features/pagination.md"}'),u={name:"3.x/ru/cms/features/pagination.md"};function k(g,a,r,d,m,v){const t=n("pre-heading"),p=n("post-heading");return o(),c("div",null,[s(t),a[0]||(a[0]=l("h1",null,"Пагинация",-1)),s(p),a[1]||(a[1]=i(`<p>October CMS включает встроенные функции пагинации, интегрированные со стандартными шаблонами и обеспечивающие полную гибкость для пользовательской разметки. Пагинированные записи тесно интегрированы с <a href="./../../extend/database/pagination.html">запросами пагинации модели</a> и <a href="./../../markup/function/pager.html">Twig-функцией <code>pager()</code></a>.</p><h2 id="пагинация-данных"><a href="#пагинация-данных" class="header-anchor">#</a> Пагинация данных</h2><p>Пагинированный набор данных может поступать из <a href="./../../extend/cms-components.html">логики компонентов</a>, из <a href="./../themes/themes.html">PHP-секции</a> страницы или макета, или из <a href="./../tailor/components.html">компонента Tailor</a>. Ниже приведён пример страницы, запрашивающей пагинированные данные из компонента Tailor с шагом <strong>10</strong> записей на страницу.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">collection</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">handle</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Blog\\Post</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> posts <span class="token operator">=</span> collection<span class="token punctuation">.</span>paginate<span class="token punctuation">(</span><span class="token number">10</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><p>Теперь переменная <code>posts</code> доступна. Мы можем перебрать каждую запись и отобразить ссылки пагинации.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> post <span class="token operator">in</span> posts <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h2</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> post<span class="token punctuation">.</span>title <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h2</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>nav</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> pager<span class="token punctuation">(</span>posts<span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>nav</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h3 id="несколько-экземпляров-пагинации"><a href="#несколько-экземпляров-пагинации" class="header-anchor">#</a> Несколько экземпляров пагинации</h3><p>По умолчанию пагинация берёт номер текущей страницы из строки запроса <code>?page</code>, поэтому один и тот же номер страницы будет использоваться при отображении двух или более наборов пагинированных данных. Для решения этой проблемы используйте метод <code>paginateCustom</code> и укажите уникальное имя параметра.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">collection blog</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">handle</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Blog\\Post</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">collection category</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">handle</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Blog\\Category</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> posts <span class="token operator">=</span> blog<span class="token punctuation">.</span>paginateCustom<span class="token punctuation">(</span><span class="token number">10</span><span class="token punctuation">,</span> <span class="token string"><span class="token punctuation">&#39;</span>postPage<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>

<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> comments <span class="token operator">=</span> comments<span class="token punctuation">.</span>paginateCustom<span class="token punctuation">(</span><span class="token number">10</span><span class="token punctuation">,</span> <span class="token string"><span class="token punctuation">&#39;</span>commentPage<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><p>Установите опцию <code>withQuery</code>, чтобы сохранить номер страницы для других экземпляров пагинации (необязательно).</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> pager<span class="token punctuation">(</span>categories<span class="token punctuation">,</span> <span class="token punctuation">{</span> withQuery<span class="token punctuation">:</span> <span class="token boolean">true</span> <span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><p>В результате строка запроса будет содержать оба номера страниц, например,<br><code>?postPage=1&amp;commentPage=2</code>.</p><h3 id="использование-пользовательскои-разметки-пагинации"><a href="#использование-пользовательскои-разметки-пагинации" class="header-anchor">#</a> Использование пользовательской разметки пагинации</h3><p>Чтобы использовать пользовательскую разметку пагинации, начните с расположений файлов ниже и скопируйте содержимое в фрагмент внутри вашей темы.</p><div class="table"><table tabindex="0"><thead><tr><th>Шаблон</th><th>Описание</th></tr></thead><tbody><tr><td><code>default</code></td><td>Стандартный шаблон пагинации.<br>Расположение: <code>~/modules/system/views/pagination/default.htm</code></td></tr><tr><td><code>simple</code></td><td>Пагинация только с кнопками «Назад» и «Вперёд».<br>Расположение: <code>~/modules/system/views/pagination/simple.htm</code></td></tr><tr><td><code>ajax</code></td><td>AJAX-пагинация записей.<br>Расположение: <code>~/modules/system/views/pagination/ajax.htm</code></td></tr></tbody></table></div><p>Затем отрендерите как фрагмент, передав опцию <code>partial</code> в pager.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> pager<span class="token punctuation">(</span>records<span class="token punctuation">,</span> <span class="token punctuation">{</span> partial<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>my-custom-pagination<span class="token punctuation">&#39;</span></span> <span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><h2 id="ajax-пагинация"><a href="#ajax-пагинация" class="header-anchor">#</a> AJAX-пагинация</h2><p>Используйте Twig-функцию <code>ajaxPager()</code> для динамического обновления пагинированных записей с помощью AJAX. Фрагмент должен отображать записи и включать пагинатор внутри, например, фрагмент с именем <strong>latest-posts.htm</strong> со следующим содержимым.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> post <span class="token operator">in</span> posts <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h2</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> post<span class="token punctuation">.</span>title <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h2</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>nav</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> ajaxPager<span class="token punctuation">(</span>posts<span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>nav</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Затем отрендерите фрагмент на странице с помощью <a href="./../../markup/tag/ajax-partial.html">Twig-тега <code>{% ajaxPartial %}</code></a>.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">collection blog</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">handle</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Blog\\Post</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> posts <span class="token operator">=</span> blog<span class="token punctuation">.</span>paginate<span class="token punctuation">(</span><span class="token number">10</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h3</span><span class="token punctuation">&gt;</span></span>Latest Posts<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h3</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">ajaxPartial</span> <span class="token string"><span class="token punctuation">&#39;</span>latest-posts<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><p>Альтернативно вы можете инкапсулировать всю логику внутри фрагмента, чтобы сделать его полностью переносимым.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">collection blog</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">handle</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Blog\\Post</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> posts <span class="token operator">=</span> blog<span class="token punctuation">.</span>paginate<span class="token punctuation">(</span><span class="token number">10</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> post <span class="token operator">in</span> posts <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h2</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> post<span class="token punctuation">.</span>title <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h2</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>nav</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> ajaxPager<span class="token punctuation">(</span>posts<span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>nav</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><p>Фрагмент затем можно отрендерить в любом месте страницы или макета без дополнительной настройки.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">ajaxPartial</span> <span class="token string"><span class="token punctuation">&#39;</span>latest-posts<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><h2 id="пагинация-«загрузить-еще»"><a href="#пагинация-«загрузить-еще»" class="header-anchor">#</a> Пагинация «Загрузить ещё»</h2><p>Кнопка «Загрузить ещё», иногда называемая бесконечным загрузчиком, — это метод отображения записей стопкой вместо разбиения на несколько страниц.</p><p>Этот подход использует AJAX-фрагмент для добавления нового содержимого вместе с самоуничтожающейся кнопкой. Например, фрагмент с именем <strong>load-more-posts.htm</strong> со следующим содержимым.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> posts <span class="token operator">=</span> blog<span class="token punctuation">.</span>paginate<span class="token punctuation">(</span><span class="token number">10</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> post <span class="token operator">in</span> posts <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h2</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> post<span class="token punctuation">.</span>title <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h2</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> posts<span class="token punctuation">.</span>hasMorePages <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
        <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onAjax<span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">data-request-update</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{ _self: &#39;@&#39; }<span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">data-request-success</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>this.remove()<span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">data-request-data</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{ page: <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> posts<span class="token punctuation">.</span>currentPage <span class="token operator">+</span> <span class="token number">1</span> <span class="token delimiter punctuation">}}</span></span> }<span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">data-attach-loading</span><span class="token punctuation">&gt;</span></span>
        Load More
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Элемент button использует комбинацию AJAX-атрибутов для выполнения <a href="./../ajax/update-partials.html">самообновления в режиме добавления</a>, передавая номер следующей страницы в качестве данных и удаляя себя после завершения.</p><p>Фрагмент должен быть отрендерен с помощью <a href="./../../markup/tag/ajax-partial.html">Twig-тега <code>{% ajaxPartial %}</code></a>.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">ajaxPartial</span> <span class="token string"><span class="token punctuation">&#39;</span>load-more-posts<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><h4 id="см-также"><a href="#см-также" class="header-anchor">#</a> См. также</h4><div class="custom-block also"><ul><li><a href="./../../extend/database/pagination.html">Пагинация моделей</a></li><li><a href="./../../markup/function/pager.html">Twig-функция pager</a></li></ul></div>`,35))])}const x=e(u,[["render",k]]);export{h as __pageData,x as default};
